"Pod inbound! Reinforcements!":"OK_PLACEHOLDER",
"Anyone remember why the sky is a portal?":"Ar kas nors prisimena, kodėl dangus yra portalas?",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"Sako, jei šoksi į šachtą, išlėksi pas priešą. Netikrinsiu.",
"The Swarm painted their visors red again. Show-offs.":"Spiečius vėl nudažė šalmų stiklus raudonai. Pasipūtėliai.",
"Ore, ore… when do we get some oil?":"Rūda, rūda… o kada gausime naftos?",
"I dreamt I was a toaster. It was peaceful.":"Susapnavau, kad esu skrudintuvas. Buvo ramu.",
"Quiet. Too quiet.":"Tylu. Per daug tylu.",
"See that? Our base is above the Swarm base again. Portals, man.":"Matėte? Virš Spiečiaus bazės vėl mūsų bazė. Tas portalas…",
"Diman, if you're reading this — we need a vacation.":"Dimanai, jei tai skaitai — mums reikia atostogų.",
