"Autosaved":"Automatiškai išsaugota",
"robot war · the sky is a portal":"robotų karas · dangus yra portalas",
"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"Sveikas atvykęs į meteoritą! Tu — Konsorciumo kovinis robotas. Apsidairyk pele ir eik: WASD.",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"Reaktyvinė kuprinė: spustelėk Shift — šuolis, laikyk Shift — skrydis. Energija atsistato ant žemės.",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"Šaudyk — kairysis pelės mygtukas. Taikytis — dešinysis pelės mygtukas: tiksliau ir su priartinimu. Padaryk kelis šūvius.",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"Perkrovimas — R. Kulkos stipriausiai pataiko vidutiniu atstumu, 20–50 metrų.",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"Raketa — Q. Prieš tankus ir pastatus. Paleisk raketą.",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"Bėk žaliomis rodyklėmis: maršrute bėgi greičiau. Užgrobk tašką — stovėk prie švyturio.",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"Tavo būrys dengia tave: kairėje jų portretai ir sveikata. Jei būrys atsilieka, kovotojai paprašys palaukti.",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — greitas kovotojo keitimas nepaliekant kovos: šuolis į būrį ar tanką arčiausiai susirėmimo. Išbandyk.",
"Next to a tank or turret press E to take control. Or just carry on.":"Šalia tanko ar bokštelio spausk E, kad jį valdytum. Arba tiesiog eik toliau.",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"Dabar strategija. Palieski „◩ Strategija“ viršuje dešinėje — vaizdas iš viršaus į mūšio lauką.",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"Dabar strategija. Spausk {0} (arba „◩ Strategija“ viršuje kairėje) — vaizdas iš viršaus į mūšio lauką.",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"Strategijoje tau padeda Kuratorius: langas viršuje sako, ką daryti, rėmelis rodo mygtuką, žiedas žymi vietą žemėlapyje. Atlik tris jo patarimus.",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"Pasirink būrį ir palieski žalią mygtuką „▶ Valdyti“ — vėl į mūšį to kareivio vietoje. Kol tu šauni, AI strategas pats vadovauja armijai.",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"Pasirink būrį ir spausk {0} arba žalią „▶ Valdyti“ — vėl į mūšį to kareivio vietoje (be pasirinkimo — savo). Kol tu šauni, AI strategas pats vadovauja armijai.",
