"Only builders build. No builder selected — the button picks the nearest idle one and starts the blueprint; then LMB on a spot.":"Stato tik inžinierius. Jei inžinierius nepasirinktas — mygtukas parinks artimiausią laisvą ir įjungs brėžinį; tada kairysis pelės mygtukas ant vietos.",
