"On — builds the base, orders troops and gives orders by itself (your orders take priority). Off — you do everything.":"Įjungtas — pats stato bazę, užsako karius ir skirsto įsakymus (tavo įsakymai svarbesni). Išjungtas — viską darai tu.",
