"Attack-move":"Eiti kovojant",
"Then click (tap) the ground: they move and fight on the way. On an enemy — attack it. Same as RMB.":"Tada spustelėk (palieski) žemę: eina ir šaudo pakeliui. Ant priešo — pulti jį. Tas pats — dešinysis pelės mygtukas.",
"Run":"Bėgte",
"Then click (tap) the ground: they run without engaging. Same as double RMB.":"Tada spustelėk (palieski) žemę: bėga nesivelsdami į kovą. Tas pats — dvigubas dešinysis pelės mygtukas.",
