"Selected groups stay put and return fire.":"Pasirinkti stovi vietoje ir šaudo atgal.",
"Retreat":"Trauktis",
"Run back to the HQ (or nearest outpost) without engaging.":"Bėgte atgal į štabą (ar artimiausią forpostą), nesivelsdami į kovą.",
"Squads jet up through the dome portal and land at the enemy.":"Būriai pakyla su jetpack, praeina kupolo portalą ir nusileidžia prie priešo.",
"Control the selected trooper, tank or turret yourself. The same key in battle brings you back to strategy.":"Pats valdyk pasirinktą kareivį, tanką ar bokštelį iš pirmo asmens. Tas pats klavišas mūšyje grąžina į strategiją.",
"4 troopers: assault, heavy gunner, rocketeer, medic.":"4 kareiviai: šturmuotojas, sunkusis kulkosvaidininkas, raketininkas, medikas.",
"Autonomous combat vehicle: cannon and MG, barrage, smoke, overdrive.":"Autonominė kovos mašina: patranka ir kulkosvaidis, salvė, dūmai, forsažas.",
"Fast flying gunner, good against infantry.":"Greitas skraidantis šaulys, geras prieš pėstininkus.",
"Elite squad with strong jetpacks — can sky-assault through the dome.":"Elitinis būrys su galingais jetpack — gali leistis desantu per kupolą.",
