"New in v6.3":"Naujiena v6.3",
"New in v6.2":"Naujiena v6.2",
"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Naujas rūdos vaizdas: rūdos gyslos — švytintys smaragdiniai briaunuoti kristalai ant juodo bazalto su kibirkštimis ir žalsva migla; ekstraktorius — šešiakampis postamentas, korio formos kupolas ir grotelių bokštas su žaliu švyturio ugnimi (juosta ir vėliavėlė — komandos spalvos)",
"New in v6.1":"Naujiena v6.1",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Pageidaujama klasė kaip Battlefield (U, skaičiai po žūties): atgimsi ja, jei įmanoma",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Technika iš pirmo asmens (V — iš išorės/iš kabinos); švelnus automatinis taikymasis — Nustatymuose",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Iš šerdies lengva išeiti: tarpas — prie šachtos, B — kapsulė į paviršių; gebėjimų efektai nusimeta žuvus",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Begalinis tobulėjimas: generolai ir Maršalas ★, karjeros lygiai, ginklų meistriškumas ir priedai, medaliai, dienos kontraktai — ekranas „Karjera“",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Strategija: sklandus artinimas ratuku, vienetų ikonos ir užrašai (Alt — visi), skydelis „Kariuomenė / Pastatai“ kairėje",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"RMB — eiti ir kovoti pakeliui, dvigubas RMB — žygis šaudant judant; retesni įsakymai — „Daugiau įsakymų ▾“; mygtukai nesikartoja",
"New in v6":"Naujovės v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Šaudymas kaip šauliuose: akimirksniu pataikančios kulkos, šautuvas 720 šūvių/min, kulkosvaidis, atatranka, taikymasis dešiniuoju pelės mygtuku, apkabos ir perkrovimas R, pataikymo žymės",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Sunkesnė gravitacija, jautresnis jetpack, šuolis Z arba dvigubas jetpack paspaudimas ore; perėjus į kitą vienetą ginklas nebeskrenda kartu",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Inžinieriai: pasirink inžinierių, pasirink pastatą, pastatyk brėžinį; ekstraktoriai ant rūdos gyslų; spustelėk „RŪDA“ — pamatysi pajamas ir kaip jas didinti",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Pilki mygtukai spaudžiami — parodysime priežastį ir sprendimo mygtuką; didesni mygtukai, juosta „Vykdoma“, „▶ Valdyti“, Tab — vienas režimo klavišas",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Strategijos kamera be trūkčiojimų ir apvertimų, artinimas į žymeklį, minižemėlapį galima tempti",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Nauja technika: reideris „Jackal“, MLRS „Grad“ (valdomos raketos), minosvaidis „Hammer“; Spiečius gauna „Wasp“, „Hive“, „Trebuchet“",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"DI strategas nebekeičia įsakymų ir nebespaudžia balsu; kovos ateina pas tave; B — permetimas, Shift+B — į kovą; kompasas, H — koks taikinys",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Laisvas žaidimas (K) ir „veikiu vienas“ (J), F2 — išankstiniai nustatymai; Esc — pauzė ir atgal; išsaugojimai: lizdai, failo eksportas ir importas",
"New in v5.3":"Naujovės v5.3",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Skrydis: toli nuo meteorito gravitacija stipresnė, C ore stabdo, trauka valdo staigiau; daugiau nebesustingsi portale",
"New in v5":"Naujovės v5",
"Endless war by default and battle scale: normal, large, epic":"Pagal numatymą begalinis karas ir kovų mastas: įprastas, didelis, epinis",
"Save and load the battle (autosave every 3 minutes)":"Kovos išsaugojimas ir įkėlimas (automatinis išsaugojimas kas 3 minutes)",
"Squadmates with callsigns: portraits, health and live chatter":"Būrys su šaukiniais: portretai, sveikata ir gyvi pokalbiai",
"Fog of war in strategy, friends and foes outlined differently":"Karo rūkas strategijoje, savi ir priešai paryškinti skirtingai",
"Camera fly-over when switching, portal aurora instead of rings":"Kameros skrydis keičiant vienetą, portalo pašvaistė vietoj žiedų",
"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"Šalutinės užduotys, trumpas kelias per dangų, pirmosios ekspedicijos moduliai su atsargomis, kristalai, ledas krateriuose, dulkių audros",
"Training, cinema mode with video recording, escort vehicles from the strategist":"Mokymai, kino režimas su vaizdo įrašymu, palydos technika iš DI stratego",
