"Grenade: hold {0} for the arc and blast circle, release to throw. Range — by view angle, wheel — power, RMB — underhand.":"Granata: laikyk {0} — lankas ir sprogimo apskritimas, paleisk — metimas. Nuotolis — žvilgsnio kampu, ratukas — jėga, DPM — metimas iš apačios.",
