"Grenades bounce and roll down slopes, 2.5 s fuse; 2 grenades, 9 s recharge; warning icon for enemy grenades nearby":"Granata atsimuša ir rieda nuolydžiu, sprogsta po 2.5 s; 2 granatos, atsistato per 9 s; piktograma įspėja apie priešo granatą šalia",
