"Grenade ({0}): hold — flight arc, blast point and radius, distance; release — throw; a quick tap throws at once. Range by view angle, wheel — power, RMB — underhand. Phone: hold G and drag.":"Granata ({0}): laikyk — skrydžio lankas, sprogimo taškas ir apskritimas, atstumas; paleisk — metimas; trumpas paspaudimas meta iš karto. Nuotolis žvilgsnio kampu, ratukas — jėga, DPM — metimas iš apačios. Telefonas: laikyk G ir vesk pirštu.",
