"The Polygon works in developer mode only":"Poligonas veikia tik kūrėjo režimu",
"⚔ Polygon: an endless battle at the map centre with reinforcements. X — possess a soldier there":"⚔ Poligonas: begalinis mūšis žemėlapio centre su nesibaigiančiais pastiprinimais. X — perimti poligono kovotoją",
