"training complete":"mokymai baigti",
"Tap \"Aim\" to zoom in. Tap again to zoom out.":"Palieski „Taikiklis“ — priartinimas. Dar kartą — atgal.",
"Your squad follows you. Open ☰ → \"Pause\" → the \"Squad with me\" tile — it becomes \"Going solo\".":"Būrys eina paskui tave. Atverk ☰ → „Pauzė“ → plytelė „Būrys su manimi“ — taps „Veikiu vienas“.",
"The builder is selected — tap \"◆ Mine crystals\" on its card below (or tap the green crystals).":"Inžinierius pasirinktas — palieski „◆ Gauti kristalus“ jo kortelėje apačioje (arba palieski žalius kristalus).",
"Training complete!":"Mokymai baigti!",
"steps":"žingsnių",
"You can build a base, order troops, command and jump into battle. Next — a real match: the Curator will help as you play.":"Moki statyti bazę, užsakyti kariuomenę, vadovauti ir šokti į mūšį. Toliau — tikras mačas: Kuratorius patars žaidimo eigoje.",
"You can move, fly, shoot, take cover and command your squad. Next — a real match.":"Moki judėti, skraidyti, šaudyti, slėptis ir vadovauti būriui. Toliau — tikras mačas.",
"Real battle":"Tikras mūšis",
"Again":"Dar kartą",
"done":"baigta",
"you are on PC: keyboard and mouse":"turi PC: klaviatūra ir pelė",
"you are on a phone: touch screen":"turi telefoną: jutiklinis ekranas",
"A safe sandbox: enemies are still dummies, nobody shoots at you. A step counts only when you actually do the action.":"Saugi smėlio dėžė: priešai — nejudantys manekenai, niekas į tave nešaudo. Žingsnis užskaitomas tik tada, kai pats atlieki veiksmą.",
"Show others (training for the other device)":"Rodyti kitus (mokymai kitam įrenginiui)",
"Old training (v7.1)":"Senieji mokymai (v7.1)",
"Back to the normal device mode":"Grįžti į įprastą įrenginio režimą",
"Training for the other device reloads the page in its mode (PC — mouse and keyboard, phone — touch; on a PC you can test touch in Chrome: F12 → phone icon).":"Mokymai kitam įrenginiui perkraus puslapį jo režimu (kompiuteris — pelė ir klaviatūra, telefonas — jutiklinis ekranas; kompiuteryje jutiklį galima išbandyti Chrome: F12 → telefono piktograma).",
"Training ×4: separate step-by-step \"Strategy\" and \"Shooter\" lessons for PC and for phone. A safe sandbox with dummies, the right button highlighted, arrows, animated keys, mouse and gestures; a step counts only for the real action, \"repeat step\", progress at the top and a reward at the end":"Mokymai ×4: atskiros žingsnis po žingsnio pamokos „Strategija\" ir „Šaulys\" kompiuteriui ir telefonui. Saugi smėlio dėžė su manekenais, paryškintas reikiamas mygtukas, rodyklės, animuoti klavišai, pelė ir gestai; žingsnis įskaitomas tik už tikrą veiksmą, „kartoti žingsnį\", eiga viršuje ir apdovanojimas pabaigoje",
"The Training menu shows the lessons for your device; \"Show others\" — all four on any device; the \"Old training (v7.1)\" is still there":"Meniu „Mokymai\" pats rodo pamokas tavo įrenginiui; „Rodyti kitus\" — visos keturios bet kuriame įrenginyje; „Senieji mokymai (v7.1)\" liko",
"New in v7.2":"Naujovės v7.2",
"NEW IN v7.2":"NAUJOVĖS v7.2",
"No grenades left":"Granatų nebėra",
"Rocket and grenade recharging · {0} s":"Raketa ir granata įkraunamos · {0} s",
"Left — move, right — look · tap an enemy — rocket / grenade · 2 taps — reflex · 3 taps — artillery strike":"Kairėje — judėti, dešinėje — apžvalga · palietimas į priešą — raketa / granata · 2 palietimai — refleksas · 3 palietimai — artilerijos smūgis",
"Less":"Mažiau",
"More":"Daugiau",
"Enemy vehicle or structure nearby — tap it: a rocket flies.":"Šalia priešo technika ar pastatas — palieski jį: išskris raketa.",
"Lots of hostiles — double tap an empty spot on the right: reflex slows time down.":"Daug priešų — greitai palieski 2 kartus laisvą vietą dešinėje: refleksas sulėtins laiką.",
"Aim at the enemy cluster and tap 3 times — artillery strike.":"Nutaikyk taikiklį į priešų spiečių ir palieski 3 kartus — artilerijos smūgis.",
"Left thumb — move, right thumb — look. Fires by itself when aimed at an enemy.":"Kairysis pirštas — judėti, dešinysis — apžvalga. Taikiklis ant priešo — ugnis pati.",
"⇑ at the left edge — jetpack: tap to hop, hold to fly.":"⇑ kairėje prie krašto — jetpack: palietimas — šuolis, laikyk — skrydis.",
"Old v7.2 layout":"Senas v7.2 išdėstymas",
"Drag a finger on the right half of the screen — a look stick appears under it.":"Vesk pirštą dešiniąja ekrano puse — po pirštu atsiras apžvalgos valdymo lazdelė.",
"Touch the left side and slide — a stick appears under your finger. Reach the green marker.":"Paliesk kairę pusę ir vesk pirštą — po pirštu atsiras valdymo lazdelė. Pasiek žalią žymę.",
"Hold the \"Jet\" button at the left edge.":"Laikyk mygtuką „Jetpack\" kairiajame krašte.",
"Aim at a dummy with the right stick — your trooper fires by itself when the crosshair is on it.":"Dešiniąja lazdele nutaikyk taikiklį į manekeną — karys šaudo pats, kai taikiklis ant taikinio.",
"Tap the dummy on the screen — a rocket flies.":"Palieski manekeną ekrane — išskris raketa.",
"Tap the dummy — a grenade flies in an arc, right at it.":"Palieski manekeną — išskris granata (į taikinį, lanku).",
"Double tap an empty spot on the right quickly.":"Greitai palieski 2 kartus laisvą vietą dešinėje.",
"Lite mode for weak phones: lower resolution, no shadows or distortion, half the bots and particles, 30 FPS cap; lowers the resolution by itself if FPS < 25. On by default on phones (Settings → Graphics → \"Lite mode\"; or ?lite=1 / ?lite=0 in the link).":"Lengvas režimas silpniems telefonams: mažesnė raiška, be šešėlių ir iškraipymų, perpus mažiau botų ir dalelių, ne daugiau kaip 30 kadrų/s; pats sumažina raišką, jei FPS < 25. Telefone įjungtas pagal numatymą (Nustatymai → Grafika → „Lengvas režimas\"; arba ?lite=1 / ?lite=0 nuorodoje).",
"Phone: new controls. Left — move, right — look (both sticks appear under your finger). Left thumb alone — \"auto\"; when the right one is used, the trooper fires by itself only while the crosshair is on an enemy. Tap an enemy — rocket or grenade, 2 taps — reflex, 3 taps — artillery strike. Auto reload. Jetpack — a button at the left edge. Bottom corners are free, minimap in the corner, hints can be closed with a cross, the objective can be collapsed. Old layout: Settings → Phone.":"Telefonas: nauja valdymo schema. Kairėje — judėti, dešinėje — apžvalga (abi lazdelės atsiranda po pirštu). Tik kairysis pirštas — „auto\"; kai dirba dešinysis, kareivis šaudo pats tik kai taikiklis ant priešo. Palietimas į priešą — raketa arba granata, 2 palietimai — refleksas, 3 palietimai — artilerijos smūgis. Perkrovimas automatinis. Jetpack — mygtukas kairiajame krašte. Apatiniai kampai laisvi, minižemėlapis kampe, užuominas galima uždaryti kryželiu, užduotį galima sutraukti. Sena schema: Nustatymai → Telefonas.",
"Hints (pop-ups and curator) — one switch in settings. Who you play as (unit or vehicle type) — \"You: …\" label in the HUD. Rifle and MG optics are transparent. The \"Arsenal\" panel is docked to the right, collapsible and switchable. \"Solo without squad\" (J) is removed. The strategist voice no longer repeats the same line. Tanks get a turret-vs-hull indicator. The cursor no longer disappears at the start of the strategy tutorial.":"Užuominos (iškylančios ir vedlio) — vienas jungiklis nustatymuose. Kuo žaidi (kariokas ar technikos tipas) — užrašas „Tu: …\" HUD'e. Automato ir kulkosvaidžio taikikliai permatomi. Skydelis „Arsenalas\" — dešinėje, sutraukiamas ir išjungiamas. Režimas „vienas be būrio\" (J) pašalintas. AI strategas nebekartoja tos pačios frazės iš eilės. Tankas turi bokšto padėties korpuso atžvilgiu indikatorių. Žymeklis nebeišnyksta strategijos mokymų pradžioje.",
