"Advanced: custom class order":"Išplėstiniai: sava klasių tvarka",
"Voice of hints & curator":"Užuominų ir vedlio balsas",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Telefonas: trys lazdelių režimai. Tik kairioji — „auto\" (stiprus magnetas, bet silpnesnės kulkos). Tik dešinioji — taikiklis įsijungia pats, stipresnis magnetas, tikslesnis šaudymas. Abi kartu — be taikiklio, silpnesnis magnetas ir tikslumas. Mygtukas 👁 dešinėje — paslėpti/grąžinti sąsają.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Telefonas: strategija supaprastinta — tik inžinierius ir pastatai. Kairėje kortelės (inžinierius, HQ, kareivinės…): palietimas — kamera skrenda ten, apačioje iškart ką statyti/gaminti. „Į kovą\" — viršuje kairėje. Armija kovoja pati. Pilna strategija — Nustatymai → Telefonas.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Valdymas — du jungikliai: „Būriai\" ir „Technika\" (telefone technika pagal numatymą išjungta — ją vairuoja DI). Kai technika išjungta, E (telefone — mygtukas dešinėje) šalia savo mašinos — sėsti prie jos pabūklo: mašina važiuoja pati, tu šauni. Sena sava klasių tvarka — „Išplėstiniuose\". Perėmus valdymą vienetas atsako per radiją.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Išmanios užuominos: bazinės užuominos pačios užgęsta po 2-o paleidimo, bet žaidimas vis tiek pasakys apie funkciją, kurios taip ir nenaudoji. Jungikliai: bazinės / pažangios / retos, atskirai — užuominų ir vedlio balsas.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Refleksas kraunasi nuo nukovimų (serija — stipriau). Bendražygiai atsiliko ar žuvo — strategas nuleidžia pas tave naujus (brangiau nei įprastas papildymas). Grafika ir garsas v7.2gfx sulieti: sprogimai kamuoliais, dūmai, nuolaužos, šachtų ir kraterių akustika. Versijos data dabar tikra.",
