"The sky is a portal: fly up and you come out on the opposite side of the meteor.":"Dangus — tai portalas: pakilęs aukštyn išeisi priešingoje meteorito pusėje.",
"Follow the strategist's orders — XP for them is doubled and tripled.":"Vykdyk stratego įsakymus — už juos patirties gausi dvigubai ar trigubai daugiau.",
"X — instantly switch to the squad or vehicle closest to the fight.":"X — akimirksniu persijungti į būrį ar mašiną, esančią arčiausiai kovos.",
