"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"Karjera ir išsaugojimai nekeičiami. Kovoje tas pats meniu — mygtukas „🛠 Meniu\" viršuje dešinėje{0}.",
"New developer match":"Naujas kūrėjo mačas",
"all unlocked, endless ore, instant build, arsenal":"viskas atrakinta, begalinė rūda, momentinė statyba, arsenalas",
"Trainings — all 4":"Mokymai — visi 4",
"PC and phone (strategy and shooter)":"Kompiuteris ir telefonas (strategija ir šaulys)",
"Cinema: split screen":"Kinas: padalytas ekranas",
"strategist bot left, shooter bot right":"kairėje botas strategas, dešinėje botas šaulys",
"Cinema: everything built":"Kinas: viskas pastatyta",
"both bases built and upgraded — for footage":"abi bazės pastatytos ir patobulintos — filmavimui",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Kino režimas — padalytas ekranas: kairėje botas strategas (vaizdas iš viršaus į bazę ir armiją), dešinėje botas šaulys iš pirmo asmens. Mygtukai apačioje (ir klavišai S, P): „Padalytas ekranas\" ir „★ Viskas pastatyta\" — abi bazės pastatytos ir patobulintos filmavimui.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Šerdies ir tunelių per meteoritą nebėra — meteoritas vientisas, kova vyksta tik paviršiuje.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Telefonas: 👁 paslepia HUD, bet palieka jetpack, ⇆, lazdeles ir užduoties žymeklį. „◎ Taikinys“ (tik dešinysis pirštas) — gerokai stipresnis ir platesnis magnetas; visų trijų režimų magneto stiprumas — Nustatymai → Valdymas → „Išplėstiniai“. Prie mašinos pabūklo mygtukas vadinasi „Nulipti“.",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Mokymai: telefone rodomi tik telefono mokymai, kompiuteryje — tik kompiuterio. Visi 4 — meniu „🛠 Kūrėjas“. Kūrėjo režimas ir Arsenalas dabar yra viename meniu (mūšyje — „🛠 Meniu“ viršuje dešinėje, kompiuteryje — F8).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"Grafikos stiliai „Dendy (8 bitų)“ ir „16 bitų“: Nustatymai → Grafika → „Grafikos stilius“ (išsamiau — mygtukas ⚙). Jei per pirmąsias ~10 s mačo FPS žemesnis nei 24, Dendy įsijungia pats (žemiau 20 — dar stambesnis pikselis, 120 eilučių); pranešimas „grįžti į įprastą“ visam laikui grąžina įprastą grafiką. Tavo pasirinkimas meniu visada svarbesnis.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"3D aplinkos modeliai (griuvėsiai, technika, įtvirtinimai) — tik gerai įvertinti, įkeliami pagal poreikį. Išjungti: Nustatymai → Grafika → „Nauji 3D aplinkos modeliai“.",
