"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Statyba kareivių rankomis: E (telefone „Įeiti“) prie savo statybvietės — kareivis stato pats, šalia esantys bendražygiai padeda. Jei inžinieriai užsiėmę, strategas pats paprašys padėti — žyma „STATYBA“.",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Stratego žymės: strategas uždeda ⌖ ant priešų sankaupos šalia tavęs — po 8 s ten smogia artilerija, o šalia esančios savos RSzU „Gradas“ paleidžia salvę. Tavo paties artilerijos smūgis iš strategijos režimo taip pat gauna „Gradų“ paramą.",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Ginklų slėptuvės krovinių konteineriuose ir nukritusiuose palydovuose (📦 matoma iš 70 m): E — sunkusis kulkosvaidis 90 s, padegamieji šoviniai ar raketos, plius pilnos granatos. Šliaužimas: Ctrl — atsigulti / atsistoti (žemiau, tyliau, tiksliau, bet lėtai).",
