"Link copied":"Nuoroda nukopijuota",
"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"„▶ Žaisti dabar“ — pirmasis meniu mygtukas: trumpas praskridimas po portalo dangumi ir tuoj pat į mūšį (praleisti — bet kuris klavišas arba palietimas).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Pataikymai juntami: metalinis garsas ir kibirkštys, nukovimo žyma prie taikiklio (šūvis į galvą — geltona), serija ×N, sklandus drebėjimas nuo sprogimų, lėtėjimas svarbių nukovimų metu. Drebėjimą, lėtėjimą ir užuominą galima išjungti Nustatymuose.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Mačo rezultatai: laikas, sunaikinimai, geriausia serija, ★ MVP ir geriausias būrys, mačo kortelė — „⇪ Dalintis“, PNG arba nuoroda į žaidimą.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Užuomina „ką daryti dabar“ kairėje po ištekliais: stratego įsakymas, užgrobtinas taškas, Spiečiaus puolimas. ✕ arba F7 — suskleisti.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Mūšis išsisaugo pats, jei uždarai ar suskleidi skirtuką — meniu „⟲ Tęsti“.",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"Versija v7.5 liko meniu „🕘 Žaidimo versija“ — jei naujoji nepatiks. Dabar siunčiama anoniminė statistika (be vardų ir el. pašto); išjungti galima Nustatymuose.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"„Žaisti dabar“, pataikymų atoveiksmis, mačo rezultatai su kortele, užuomina „ką daryti“, automatinis išsaugojimas",
"and older: v7.5, v7.4, milestones v1–v7.0":"ir senesnės: v7.5, v7.4, etapai v1–v7.0",
"New in v7.6":"Naujovės v7.6",
"NEW IN v7.6":"NAUJOVĖS v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Frakcijos pasirinkimas prieš mačą: „Konsorciumas“ (sunkioji pėstininkija galios šarvuose, šarvai ir artilerija) arba „Spiečius“ (greitis, dronų pulkai, sunkūs šūviai su iškraipymu). AI žaidžia už kitą. Pasirinkimas įsimenamas.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Kiekviena frakcija turi savo techniką ir unikalumų: Konsorciumas — tanką „Raganosis“ ir „Keramito plokštes“, Spiečius — „Dronų pulką“ ir „Fazinius jetpack'us“. Balansas patikrintas botų mačais.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Sprogimų krateriai: artilerija, raketos ir tankų patrankos kasa duobes meteorite — jomis galima vaikščioti ir važiuoti, o viduje galima pasislėpti.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Trečiojo asmens vaizdas kareiviui (V, prisimenamas; telefone — Valdymas) ir sklandi technikos kamera su žyme, kur pataikys patranka.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"v7.6 liko meniu „🕘 Žaidimo versija“ — jei nauja nepatiks.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Frakcijos „Konsorciumas“ / „Spiečius“ su pasirinkimu prieš mačą, sprogimų krateriai, trečiojo asmens vaizdas",
"and older: v7.6, v7.5, milestones v1–v7.0":"ir senesnės: v7.6, v7.5, gairės v1–v7.0",
