"Anomaly ahead! The vein is singing — go around!":"Anomalija priekyje! Gysla dainuoja — aplenkiame!",
"Hear that hum? A singing vein. Keep clear!":"Girdite ūžesį? Dainuojanti gysla. Nesiartinkite!",
"Anomaly! The air is swirling — a whirlpool, go around!":"Anomalija! Oras sukasi — tai verpetas, aplenk!",
"Rocks floating in the air… A whirlpool! Stay out!":"Akmenys kabo ore… Verpetas! Nelįsk!",
"Anomaly ahead — it is crackling with current!":"Anomalija priekyje — traška srove!",
"Rods and lightning — a Crackler. It loves armour!":"Strypai ir žaibai — Traškutis. Šarvus jis mėgsta!",
"Anomaly! The ground shimmers with heat — a Brazier!":"Anomalija! Žemė virpa nuo karščio — Žarijinė!",
"Careful, a Brazier underfoot!":"Atsargiai, po kojomis Žarijinė!",
"Anomaly — green mist! Acid, hold your breath!":"Anomalija — žalias rūkas! Rūgštis, nekvėpuojame!",
"The mist is drifting our way, go around!":"Rūkas slenka link mūsų, aplenkiame!",
"Anomaly! The air is like glass — a Lens, it bends bullets!":"Anomalija! Oras kaip stiklas — Lęšis, lenkia kulkas!",
"Everything is warping… a Lens nearby!":"Vaizdas plaukia… Lęšis šalia!",
"Ha! An enemy walked right into the anomaly!":"Ha! Priešas įlindo tiesiai į anomaliją!",
"Got him! Lure them into anomalies!":"Pagavo! Viliok juos į anomalijas!",
"Beautiful zap! One less tin can.":"Gražiai trinktelėjo! Minus skardinė.",
"The anomaly got me!":"Anomalija mane užkabino!",
