" — close":" — uždaryti",
"Supply drop":"Atsargų dėžė",
"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"Nuleidžia dėžę prie jūsų pajėgų: šovinius, granatas, raketas, ginklo dalis, remonto rinkinį.",
"\"Grad\" rocket strike":"„Grado“ raketų smūgis",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"16 raketų dideliame plote po 3 sekundžių — greičiau ir plačiau nei artilerijos smūgis.",
"Support: crate, recon, \"Grad\", artillery (then 1–4)":"Parama: dėžė, žvalgyba, „Gradas“, artilerija (tada 1–4)",
"WARNING: Swarm \"Grad\" incoming on your area!":"DĖMESIO: Spiečiaus „Gradas“ pataikė į jūsų rajoną!",
"Warning! Rocket salvo on our position!":"Dėmesio! Raketų salvė į mūsų poziciją!",
"take the supply crate":"paimti atsargų dėžę",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"Anomalijos meteorite (1 banga): „Dainuojanti gysla“ — švytintis žalias kristalas, ūžia ir ritmingais impulsais smogia visiems šalia; „Verpetas“ traukia ir svaido, „Traškutis“ šaudo žaibais tarp strypų, „Žarijinė“ užsiliepsnoja po kojomis, „Rūgštinis rūkas“ ir „Lęšis“ (lenkia kulkas ir vaizdą) dreifuoja aplink.",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"Anomalijas pajusti galima iš anksto (ūžesys, švytėjimas, karščio miražas). Iškrauk granata, raketa arba varžtu (E prie jos): ji užmigs, kartais palieka artefaktą su pliusu ir minusu. Būrys įspėja per radiją, o priešai (ir savi) kartais į jas įlenda — viliok!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"Parama už komandos taškus: 4 mūšyje (📡 telefone) — atsargų dėžė, žvalgyba, „Grado“ raketų smūgis, artilerijos smūgis pagal taikiklį. Strategas anomalijas žemėlapyje mato tik po žvalgybos.",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"Atsargų dėžės senų ekspedicijų griuvėsiuose, prie štabų ir šalia pastatytų pastatų: šoviniai, granatos, raketos, ginklo dalys (atrakina priedus).",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"v7.7 liko meniu „🕘 Žaidimo versija“. Anomalijas galima išjungti Nustatymuose.",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"Anomalijos („Dainuojanti gysla“ ir dar 5), iškrovimas varžtu ar granata, artefaktai, parama už komandos taškus, atsargų dėžės",
"and older: v7.7, v7.6, milestones v1–v7.0":"ir senesnės: v7.7, v7.6, gairės v1–v7.0",
"New in v7.8":"Naujiena v7.8",
"NEW IN v7.8":"NAUJIENA v7.8",
"Close":"Uždaryti",
"Anomalies on the meteor":"Anomalijos meteorite",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"☰ kampe atidaro pauzės meniu: Tęsti, Pradėti iš naujo, Mokymai, Grafika, Nustatymai, Pagrindinis meniu (su patvirtinimu). Telefonas: ☰ viršuje dešinėje (mūšio veiksmai — plytelė „⚡ Veiksmai“); kompiuteris: mygtukas „☰ Meniu“ viršuje dešinėje arba Esc.",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"Grafika pagal numatytuosius nustatymus visada įprasta — Dendy tik jei pasirinksi: jungiklis „Grafika: Įprasta / Dendy (8 bitų) / 16 bitų“ tiesiai pagrindiniame meniu ir pauzėje. Jei žaidimas smarkiai stringa, atsiranda patarimas su mygtuku „Įjungti Dendy“.",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"Telefonas ir planšetė: veiksmo mygtukas „✋“ dešinėje atsiranda tik kai šalia yra ką daryti — „Paimti“ (slėptuvė, dėžė), „Sėsti“ (technika, bokštelis, pabūklas), „Statyti“, „Nulipti“, „Varžtas“ prie anomalijos. Galima ir tiesiog paliesti paryškintą objektą.",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"Telefonas, strategija: laikyk pirštą ~0,3 s (telefonas suvirpės, atsiras geltonas žiedas) ir veski — pažymėjimo rėmelis; įprastas brūkštelėjimas stumdo kamerą. Yra ir mygtukas „Rėmelis“ dešinėje; mokymuose žingsnis „Rėmelis“ užskaito ir būrio pasirinkimą palietimu.",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"Telefonas: smulkius mygtukus lengviau paspausti, 📡 paramos sąrašas didesnis, strategijos skydeliai nebeužstoja pauzės ir rezultatų ekranų. v7.8 liko meniu „🕘 Žaidimo versija“.",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"☰ meniu telefone ir kompiuteryje, jokio automatinio Dendy, mygtukas „✋“ jutikliniame ekrane, pažymėjimas rėmeliu telefone",
"16-bit":"16 bitų",
"Lagging? Try the Dendy graphics — they are lighter.":"Stringa? Išbandyk Dendy grafiką — ji lengvesnė.",
