"Commander · soon":"Vadas · greitai",
"Commander — still in development":"Vadas — dar kuriamas",
"Pause: resume, restart, training, graphics, settings, main menu":"Pauzė: tęsti, iš naujo, mokymai, grafika, nustatymai, pagrindinis meniu",
"Menu: pause, restart, training, graphics, settings":"Meniu: pauzė, iš naujo, mokymai, grafika, nustatymai",
"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Laikyk pirštą ant žemės ~0,3 s — telefonas suvirpės ir atsiras geltonas žiedas — ir, nepaleisdamas piršto, veski: atsiras rėmelis. Arba mygtukas „Rėmelis“ dešinėje. Galima ir tiesiog paliesti būrį.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"Pilnam ekranui iPhone: „Bendrinti“ ⬆ → „Pridėti prie pagrindinio ekrano“ — žaidimas atsidarys be Safari juostų.",
"Open portal-meteor.pages.dev for that.":"Tam atidaryk svetainę portal-meteor.pages.dev.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Palietimas — pažymėti · palietimas ant žemės — eiti · laikyk — įsakymų meniu · laikyk ir veski — rėmelis · 2 pirštai — mastelis",
"Robo-ninja":"Robo-ninja",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"Herojė žudikė: šuoliai-teleportai, katana, šurikenai. Pati šokinėja per priešo zonas ir kapoja robotus. 1 kiekvienai pusei.",
"Shadow protocol":"Protokolas „Šešėlis“",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"Tyrimas: atrakina robo-nindzę Kareivinėse. Reikia pastatytos mechų gamyklos.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Herojė (1 kiekvienai pusei): pati teleportuojasi per priešo zonas ir kapoja robotus; gali perimti valdymą ir žaisti rankiniu būdu.",
"is ready. She works on her own (AUTO) — possess her to play manually":"paruošta. Dirba pati (AUTO) — perimk valdymą, kad žaistum rankiniu būdu",
"Robo-ninja ready for action":"Robo-nindzė pasirengusi kovai",
"⚠ Intel: the enemy has a robo-ninja!":"⚠ Žvalgyba: priešas turi robo-nindzę!",
"Warning! The enemy has a robo-ninja. Stay together":"Dėmesio! Priešas turi robo-nindzę. Laikykitės drauge",
"cyber blinks":"kibernetiniai šuoliai",
"Too far for a dash — get closer or teleport":"Per toli šuoliui — prieik arčiau arba teleportuokis",
"point ":"taškas ",
"enemy group":"priešo grupė",
"order":"įsakymas",
"nearby":"šalia",
"Zone cleared":"Zona išvalyta",
"⚔ NINJA DUEL! Block right before a hit to parry, blink to dodge. Watch for the wind-up flash":"⚔ NINDZIŲ DVIKOVA! Blokuok prieš pat smūgį — pariravimas, šuolis — išsisukimas. Stebėk užsimojimo blyksnį",
"The two ninjas have met in a duel!":"Dvi nindzės susitiko dvikovoje!",
"⚔ Duel won! Our ninja prevails":"⚔ Dvikova laimėta! Mūsų nindzė stipresnė",
"⚔ Duel lost…":"⚔ Dvikova pralaimėta…",
"ninja duel":"nindzių dvikova",
"POSTURE BROKEN":"PUSIAUSVYRA SUGRIAUTA",
"Teleport":"Teleportas",
"Teleport: aim at the ground (up to 150 m)":"Teleportas: nutaikyk į žemę (iki 150 m)",
"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ AUTO: pati šokinėja per priešo zonas ir kapoja. Lazdelė / WASD — pauzė 1.5 s",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ Rankinis: palietimas ant priešo — šuolis ir smūgis, brūkštelėjimas — kirtis, 🛡 — blokas",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ Rankinis valdymas: kairysis pelės mygtukas — katana, dešinysis pelės mygtukas — blokas, Shift — šuolis, Q — šurikenai, G — teleportas",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ Nindzė: palietimas ant priešo — šuolis ir kirtis, brūkštelėjimas dešinėje — kirtis, ● — smūgis, 🛡 — blokas (laiku = atmušimas), ⇑ — šuolis, ✦ — shurikenai, ◎ — teleportas, AUTO — pati",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ Nindzė: kairysis pelės mygtukas — katana (laikyk — sunkus kirtis), dešinysis pelės mygtukas — blokas (laiku = atmušimas), Shift/Z — šuolis, Q — shurikenai, G — teleportas į taikiklį, šuolis ore — dvigubas šuolis / bėgimas siena, {0} — AUTO",
