"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Radijas Portal Meteor: 100+ EDMITRY takelių tiesiog žaidime — mygtukas 📻 (kompiuteryje: klavišas 5, [ ] — takelis). Muzika srautu perduodama pagal poreikį ir neapkrauna žaidimo; garsumas ir automatinis paleidimas — Nustatymuose, taip pat nuoroda „Klausyti Spotify“.",
