"Radio Portal Meteor (EDMITRY): volume":"Radijas Portal Meteor (EDMITRY): garsumas",
"Radio: start by itself in battle":"Radijas: pačiam įsijungti kovoje",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Robo-nindzė: kiborgė su katana. Atrakinama Kareivinėse tyrimu „Šešėlio protokolas“ (reikia mechų gamyklos). Pati teleportuojasi į priešo zonas, kapoja priešus į gabalus (be kraujo — kibirkštys), šuoliai, shurikenai, dvikovos su priešo nindze. Valdyk ją (Possess) — režimas AUTO arba rankinis valdymas (telefone — savi mygtukai).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Radijas Portal Meteor: 103 EDMITRY takeliai tiesiog žaidime. Klavišas 5 (perkeliamas), telefone — ☰ → Nustatymai → Garsas. Garsumas ir „pačiam įsijungti kovoje“ — nustatymuose; muzika patyli per sprogimus ir radijo balso metu.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Naujos kalbos: uzbekų ir tadžikų — visiškai; kinų, ispanų, portugalų — iš dalies. Naujas kalbos pasirinkimas meniu šalia „Naujas mačas“.",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Telefonas: „slėpti piktogramas“ 👁 surenka likusius mygtukus į tvarkingą stulpelį dešiniajame krašte; portretinis režimas nebeslepia; iPhone — žaidimas nebesikivirčija su Safari gestais, o „Bendrinti → Pridėti prie pagrindinio ekrano“ paleidžia jį per visą ekraną.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"Iš v7.8.1: kampinis meniu ☰ (pauzė, iš naujo, mokymai, grafika), be automatinio Dendy, ✋ veiksmo mygtukas telefone. v7.8.1 ir v7.8 liko meniu „🕘 Žaidimo versija“.",
