"The bomber took off from the base — into the sky, it will come out over the target":"Bombonešis pakilo iš bazės — išskrenda į dangų ir pasirodys virš tikslo",
"Select a unit → \"▶ Possess\" or double-tap. Mode button at the top right: Strategist → Commander → Shooter.":"Pažymėk vienetą → „▶ Perimti valdymą“ arba dvigubas palietimas. Režimo mygtukas viršuje dešinėje: Strategas → Vadas → Šaulys.",
"Select a unit → \"▶ Possess\" or double-click. {0} cycles: Strategist → Commander → Shooter.":"Pažymėk vienetą → „▶ Perimti valdymą“ arba dvigubas spustelėjimas. {0} — ratu: Strategas → Vadas → Šaulys.",
