"Living world: requests, hero quests, breakthrough ops":"Gyvas pasaulis: savų prašymai, herojų užduotys, lemiamas mūšio posūkis",
"Living world":"Gyvas pasaulis",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Savi prašo pagalbos ir apdovanoja, herojai duoda užduotis, užsitęsusį frontą pralaužia operacija",
"A request":"Savų prašymas",
"Breakthrough":"Lemiamas posūkis",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Savi kartais prašo pagalbos: balsas per radiją, kortelė „PRAŠYMAS“ ir žymė ✋. Būrį prispaudė — sunaikink šalia esančius priešus. Atlygis: kareivis kapsule iš bazės, ginklas iš automobilio bagažinės, šaulio vieta arba orbitinis dengimas. Ne dabar — ✕ arba tiesiog ignoruok.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Veteranas žvalgas „Pelėda“ siūlo užduotį. Y — priimti (N — atsisakyti). Eik prie žymės ★, pašalink sargybą ir pastovėk prie piloto 3 s — jis prisijungs prie tavo būrio.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Frontas sustojo — štabas siūlo lemiamą posūkį. Y — priimti. Laikyk retransliatorių 8 s be priešų šalia: priešo žemėlapis matomas 60 s. Generatorius — priešo bokšteliai tyli 2 min. Strategu — „Paskirti būriui“. Priešas taip pat gali: stebėk ⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Savi prašo pagalbos: kortelė „PRAŠYMAS“ ir žymė ✋. Sunaikink priešus prie prispausto būrio — gausi atlygį. ✕ — praleisti.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"Herojus „Pelėda“ siūlo užduotį — palieski „Priimti“. Eik prie ★, pašalink sargybą, pastovėk prie piloto.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Frontas sustojo — palieski „Priimti“ ir laikyk retransliatorių 8 s: priešo žemėlapis atsivers minutei.",
"Pod redeploy from the base: {0} m — through the sky portal":"Perkėlimas kapsule iš bazės: {0} m — per dangaus portalą",
"Pod away from the base! Hold on — exit over the target.":"Kapsulė iškeliavo iš bazės! Laikykitės — išėjimas virš tikslo.",
