"An engineer brushed the fluff off":"Inžinierius nuvalė pūką",
"The fluff fell off — armour is safe":"Pūkas nukrito — šarvai sveiki",
"The firefly swarm scattered by the blast":"Jonvabalių spiečių išsklaidė sprogimas",
"STEEL FLUFF −2/s · stand still 3 s or find an engineer":"PLIENO PŪKAS −2/s · stovėk 3 s ne kovoje arba pas inžinierių",
"Lefty's convoy is ready: two Jackals. Stay close — they wait for you":"„Kairiarankio“ vilkstinė paruošta: du „Šakalai“. Laikykis šalia — be tavęs jie lauks",
"The convoy is waiting for you":"Konvojus tavęs laukia",
