"Builds structures and extractors, repairs, cleans Steel fluff off others.":"Stato pastatus ir ekstraktorius, taiso, nuvalo Plieno pūką nuo kitų.",
"A squad flies from the base launch pad through the sky portal right to the target.":"Būrys atskrenda nuo bazės paleidimo aikštelės per dangaus portalą tiesiai į taikinį.",
"Squad: ":"Būrys: ",
