"Three modes on one button: Shooter (you fight yourself), the new Commander (lead one squad, 4 abilities per unit type) and Strategist. On the phone — a simple interface: fewer buttons, modes unlock during the battle.":"Trys režimai vienu mygtuku: Šaulys (pats kovoji), naujasis Vadas (vedi vieną būrį, kiekvieno tipo 4 gebėjimai) ir Strategas. Telefone — paprasta sąsaja: mažiau mygtukų, režimai atrakinami mūšio eigoje.",
"Living meteor: rocks, ridges, a hangar in a mesa, lava / ice / methane lakes, three biomes, local weather, new anomalies and native fauna.":"Gyvas meteoritas: uolos, kalnagūbriai, angaras stalkalnyje, lavos, ledo ir metano ežerai, trys biomai, vietinis oras, naujos anomalijos ir vietinė fauna.",
"Factions play differently: the Swarm digs tunnels and regenerates, the Consortium builds barriers and repairs. From minute 12 — the Bastion and Reaper bosses; you can possess your own.":"Frakcijos tapo skirtingos: Spiečius kasa tunelius ir regeneruojasi, Konsorciumas stato užtvaras ir taiso techniką. Nuo 12-os minutės — bosai „Bastionas\" ir „Reaper\"; savąjį galima perimti.",
"Living world: your troopers ask for help over the radio (with a reward), heroes give quests, a stalled front gets a \"Breakthrough\" operation. Capsules, crates and strikes launch from the base through the sky portal.":"Gyvas pasaulis: savi kareiviai prašo pagalbos per radiją (už atlygį), herojai duoda užduotis, užstrigus frontui — operacija „Mūšio posūkis\". Kapsulės, dėžės ir smūgiai startuoja iš bazės per dangaus portalą.",
"Faster (a frame up to 2x cheaper), gamepad in every mode, tablet layout, an encyclopedia of everything in the game, feedback mode — a note with a screenshot on one key.":"Greičiau (kadras iki 2 kartų pigesnis), gamepad visuose režimuose, planšetės išdėstymas, visko žaidime enciklopedija, atsiliepimo režimas — pastaba su ekrano nuotrauka vienu klavišu.",
"All new texts are translated into Uzbek, Tajik, Chinese, Spanish, Portuguese and Hebrew. The v7.9 ninja and radio stay; v7.9 is in the \"🕘 Game version\" menu.":"Visi nauji tekstai išversti į uzbekų, tadžikų, kinų, ispanų, portugalų ir hebrajų kalbas. v7.9 robo-ninja ir radijas liko vietoje; v7.9 yra meniu „🕘 Žaidimo versija\".",
